import{_ as i,h as s,i as a,c as n,v as t,p as r,x as l,m as p,e as m,S as E}from"./chunks/framework.Dvtg8yj2.js";const P=JSON.parse('{"title":"Test-time compute scaling","description":"","frontmatter":{"title":"Test-time compute scaling","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/test-time-scaling.md","filePath":"llm/test-time-scaling.md","lastUpdated":1788454257000}'),c={name:"llm/test-time-scaling.md"};function d(h,e,A,B,u,f){const o=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="test-time-compute-scaling" tabindex="-1">Test-time compute scaling <a class="header-anchor" href="#test-time-compute-scaling" aria-label="Permalink to &quot;Test-time compute scaling&quot;">​</a></h1><div class="epigraph"><p>按题目难度把推理期算力用对，可以比继续加大预训练参数更有效；最优策略不是对所有提示都做同一种更贵的解码。</p><footer>—— Snell, Lee, Xu, Kumar, Scaling LLM Test-Time Compute Optimally can be More Effective than Scaling Model Parameters, 2024</footer></div><p>预训练缩放定律问的是：参数与数据再涨一个数量级，损失掉多少。测试时计算（test-time compute）问的是：对 <em>已经训好</em> 的模型，在这一题上再花 FLOPs——更长的思维链、更多候选、更深的树——准确率还能涨多少。OpenAI 在 2024 年 9 月关于 o1 的公开博客里，把「用强化学习训练、在回答前花更多时间思考」写成产品叙事；可引用的机制实验，应以 Snell 等人 2024 年的公开论文为主，而不是给 o1 补一套未发表的公式。本篇写测试时缩放的对象、两条主路径，以及「计算最优」为什么必须分难度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一道题，贪婪短答可能错，采样 8 条再核对可能对，让模型先写两千 token 的草稿纸也可能对。三种做法花的是不同形态的推理算力：<a href="/llm/prefill-compute">Prefill</a> 几乎不变（提示相同），Decode 的 token 数、并发条数或树节点数在变。账单按生成 token 与 KV 带宽走，见<a href="/llm/decode-memory-wall">显存墙</a>。若把测试时预算当成与参数量可互换的通货，必须问：在 <em>匹配 FLOPs</em> 下，花在更大模型的预训练上，还是花在小模型的更长搜索上。</p><p>Snell 等人指出，答案随 <strong>提示难度</strong> 变。简单题上，<a href="/llm/best-of-n">Best-of-N</a> 很快饱和，再加 \\(N\\) 几乎只买重复；中等题上，过程引导的搜索可能显著好于盲目加宽；很难的题上，小模型无论怎么搜也可能达不到大模型短解码的水平——搜索不能发明预训练里不存在的知识。把「测试时缩放万能」写成定律，忽略了这道分界。</p><h3 id="两条机制不要合成一句广告" tabindex="-1">两条机制不要合成一句广告 <a class="header-anchor" href="#两条机制不要合成一句广告" aria-label="Permalink to &quot;两条机制不要合成一句广告&quot;">​</a></h3><p>论文里讨论的主路径大致是：（1）在稠密的过程验证器上做搜索（束、lookahead，与 <a href="/llm/mcts-llm">MCTS</a> 近亲）；（2）根据提示调整模型在答案上的分布——包括更长的思维链、修订，而不是固定短答。o1 类产品把（2）做成默认用户体验：延迟与费用随「思考」上升。公开博客没有给出与 Snell 逐项对齐的消融，写系统对比时不要把博客曲线和论文表格画成同一张图。</p><p><span class="marginnote">「思考时间」不是架构超参。权重不变，变的是解码程序与停止条件。截断 <code>max_tokens</code> 或关掉思考开关，测到的是另一条计算—准确率曲线。评测必须把测试时预算写成方法的一部分，与模型卡上的参数量并列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先固定基座 \\(\\pi\\) 与总预算 \\(C\\)（生成 token、模拟次数或墙钟）。再选分配器：</p><ul><li><strong>宽度</strong>：独立采样 \\(N\\) 条，用 ORM / 多数票 / PRM 聚合选一条。</li><li><strong>深度</strong>：单条链写得更长，或逐步扩展再回溯。</li><li><strong>自适应</strong>：用一个难度探针（小试探、自洽不确定性、或训练过的难度头）把 \\(C\\) 分给不同提示——简单题 \\(N=1\\)，难题才搜。</li></ul><p>Snell 等人的计算最优（compute-optimal）指：在每个难度桶上选当时收益最大的那种策略，而不是全局一种 BoN。他们报告在部分设定下，相对盲目 Best-of-N，合适的分配可以把测试时缩放效率提高一个可观倍数；在 FLOPs 匹配比较中，当小模型在该题上已有不可忽略的成功率时，测试时计算可以超过参数量大一个数量级的短解码。这些数字以原文图表为准，不要改写成「14× 永远成立」。</p>',13)),(a(),r(E,null,{default:l(()=>[m(o,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%A2%98%E7%9B%AE%20%2B%20%E9%A2%84%E7%AE%97%20C%22%5D%20--%3E%20D%7B%22%E9%9A%BE%E5%BA%A6%20%2F%20%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%22%7D%0A%20%20D%20--%3E%7C%E6%98%93%7C%20W%5B%22%E7%9F%AD%E8%A7%A3%E7%A0%81%E6%88%96%E5%B0%8F%20N%22%5D%0A%20%20D%20--%3E%7C%E4%B8%AD%7C%20S%5B%22PRM%20%E6%9D%9F%20%2F%20lookahead%22%5D%0A%20%20D%20--%3E%7C%E9%9A%BE%7C%20L%5B%22%E6%9B%B4%E5%A4%A7%20N%20%E6%88%96%E6%9B%B4%E9%95%BF%E9%93%BE%EF%BC%9B%E4%BB%8D%E5%8F%AF%E8%83%BD%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20W%20--%3E%20OUT%5B%22%E7%AD%94%E6%A1%88%22%5D%0A%20%20S%20--%3E%20OUT%0A%20%20L%20--%3E%20OUT%0A%20%20OUT%20--%3E%20M%5B%22%E7%94%A8%E7%9C%9F%E5%80%BC%E8%AF%84%E6%B5%8B%EF%BC%8C%E4%B8%8D%E6%98%AF%E7%94%A8%20s%20%E7%9A%84%E5%88%86%E6%95%B0%E5%BD%93%E5%94%AF%E4%B8%80%E6%8C%87%E6%A0%87%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="与预训练缩放对照" tabindex="-1">与预训练缩放对照 <a class="header-anchor" href="#与预训练缩放对照" aria-label="Permalink to &quot;与预训练缩放对照&quot;">​</a></h3><p>Kaplan / Chinchilla 一类定律描述训练损失随参数、数据、训练 FLOPs 的变化。测试时缩放描述的是 <em>推理 FLOPs</em> 对下游准确率。两者单位都是 FLOPs，但边际收益的形状不同：训练 FLOPs 改变权重，对所有未来提示摊销；测试 FLOPs 每次查询重付。产品上只有高频、高价值查询才值得把测试预算加到与预训练边际可比。把「小模型 + 狂搜」当通用部署策略，会在开放聊天上买来延迟，却买不来知识。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>宽度扩展覆盖 \\(\\pi\\) 的多模式：正确模式以概率 \\(p\\) 出现时，独立样本把失败打到 \\((1-p)^N\\)。深度扩展改变的是 <em>单条轨迹内部的计算</em>：更多中间 token 让模型做自检、换解法，这要求 \\(\\pi\\) 在训练时已经被激励去使用长链（强化学习、长链 SFT），否则加长只是重复套话。过程验证器让深度搜索有可反向的逐步 \\(Q\\)，否则深度与宽度都会在错误的目标上浪费预算。</p><p>自适应之所以必要，是因为 \\(p\\) 随题变。对 \\(p\\approx 1\\) 的题，任何搜索的一阶导数接近 0；对 \\(p\\approx 0\\) 的题，导数也可能接近 0，直到 \\(N\\) 大到不现实，或直到知识根本不在模型里。中间区才是测试时计算的甜点。难度估计本身会错：把难题估成易题，等于拒绝给预算；把易题估成难题，等于给用户买延迟。探针应保守，并在产品里允许用户强制「快/慢」覆盖。</p><p><span class="marginnote">匹配 FLOPs 时要写清比较的是预训练 FLOPs 还是该次推理 FLOPs。用「小模型搜了 100 次」去比「大模型只答一次」可以，但必须把 100 次 decode 算进左侧。只比参数量不比生成 token，结论是空的。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="公开论文与封闭系统分开引用" tabindex="-1">公开论文与封闭系统分开引用 <a class="header-anchor" href="#公开论文与封闭系统分开引用" aria-label="Permalink to &quot;公开论文与封闭系统分开引用&quot;">​</a></h3><p>Snell et al., 2024（arXiv:2408.03314）是可核对的测试时缩放实验。OpenAI o1 的公开文本是产品与安全报告级描述，没有同等程度的解码器与搜索消融。DeepSeek-R1 把测试时变长思维写成 RL 的结果，搜索主要在训练期被内化进 \\(\\pi\\)，推理可以不再跑显式 BoN——这是第三条路：把测试时行为 <em>训练进权重</em>。三条路的成本落点不同，不能用同一张「缩放曲线」覆盖。</p><p>验证器错误会随搜索预算被放大，见 BoN 的过优化。安全与拒答策略必须进入 \\(s\\)，否则更多测试时计算等于更强的对抗搜索。服务上应把思考预算与 KV 池、队列优先级绑在一起：默认全开长链会把共享集群的 decode 打满。不要用针测或短上下文聊天的 SLA 去承诺竞赛级思考延迟。</p><p><span class="marginnote">禁止把未公开的 o1 内部报告写成 arXiv 论文。需要封闭系统数字时，引用官方博客日期与当时的基准声明，并注明不可复现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>测试时缩放：固定权重，用更多推理计算换准确率；预算要按生成 token / 搜索结构记账。</li><li>宽度（BoN）与深度（长链、树）机制不同；最优组合随题目难度变。</li><li>计算最优是按桶选策略，不是全局加大 \\(N\\)。</li><li>很难的题上搜索补不齐预训练缺失的知识；很简单的题上搜索很快饱和。</li><li>FLOPs 匹配必须声明比较的是训练还是该次推理；摊销逻辑完全不同。</li><li>o1 公开叙事与 Snell 2024 应分开引用；R1 把长链训练进策略，推理可不显式搜。</li><li>出处：Snell et al., 2024, arXiv:2408.03314；OpenAI, <em>Learning to Reason with LLMs</em>, 2024 年 9 月博客；DeepSeek-AI, <em>DeepSeek-R1</em>, 2025。</li></ul>',13))])}const D=i(c,[["render",d]]);export{P as __pageData,D as default};
